        /**
         * Redondeo bancario y fiscal exacto sin desfase de coma flotante
         */
        redondear(val, decimals = 2) {
            if (isNaN(val) || val === null || val === undefined) return 0;
            const factor = Math.pow(10, decimals);
            return Math.round((Number(val) + Number.EPSILON) * factor) / factor;
        },

        /**
         * Conversor de unidades de materia prima y recetas
         */
        convertirUnidadInsumo(cant, unidadOrigen, unidadDestino) {
            const uO = (unidadOrigen || '').toLowerCase().trim();
            const uD = (unidadDestino || '').toLowerCase().trim();
            if (uO === uD) return cant;
            if (uO === 'g' && uD === 'kg') return cant / 1000;
            if (uO === 'kg' && uD === 'g') return cant * 1000;
            if (uO === 'ml' && uD === 'lt') return cant / 1000;
            if (uO === 'lt' && uD === 'ml') return cant * 1000;
            if (uD.includes('45kg') || uD.includes('saco')) return cant / 45;
            if (uD.includes('50kg')) return cant / 50;
            if (uD.includes('25kg')) return cant / 25;
            if (uD.includes('15kg')) return cant / 15;
            return cant;
        },
        
