        obtenerFotoEmpleado(emp, hd = false) {
            if (!emp) return `https://ui-avatars.com/api/?name=Viasa+Personal&background=1e1b4b&color=fbbf24&bold=true&size=${hd ? 512 : 256}`;
            
            // Si el trabajador tiene expresamente configurado sin foto o avatar por defecto
            if (emp.sinFoto === true || emp.foto === 'none' || emp.foto === 'avatar_default') {
                const nom = emp.nombreCompleto || 'Trabajador Viasa';
                return `https://ui-avatars.com/api/?name=${encodeURIComponent(nom)}&background=1e1b4b&color=fbbf24&bold=true&size=${hd ? 512 : 256}`;
            }

            let url = emp.fotoBase64 || emp.fotoUrl || emp.foto;

            const defaultPhotos = {
                'EMP-001': 'https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&w=1000&h=1000&q=90',
                'EMP-002': 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=1000&h=1000&q=90',
                'EMP-003': 'https://images.unsplash.com/photo-1583394293214-28ded15ee548?auto=format&fit=crop&w=1000&h=1000&q=90',
                'EMP-004': 'https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?auto=format&fit=crop&w=1000&h=1000&q=90',
                'EMP-005': 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=1000&h=1000&q=90',
                'EMP-006': 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=1000&h=1000&q=90',
                'EMP-007': 'https://images.unsplash.com/photo-1567532939604-b6b5b0db2604?auto=format&fit=crop&w=1000&h=1000&q=90',
                'EMP-008': 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=1000&h=1000&q=90',
                'EMP-009': 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=1000&h=1000&q=90'
            };

            if (!url && !emp.sinFoto && emp.id && defaultPhotos[emp.id]) {
                url = defaultPhotos[emp.id];
            }

            if (url) {
                if (hd && url.includes('images.unsplash.com')) {
                    return url.replace(/w=\d+&h=\d+&q=\d+/, 'w=1200&h=1200&q=95');
                }
                return url;
            }

            const nom = emp.nombreCompleto || 'Trabajador Viasa';
            return `https://ui-avatars.com/api/?name=${encodeURIComponent(nom)}&background=1e1b4b&color=fbbf24&bold=true&size=${hd ? 512 : 256}`;
        },

