        enviarTicketWhatsApp() {
            const v = this.ultimaVenta;
            if (!v) return;

            let texto = `🥖 *PANADERÍA Y PASTELERÍA NUEVA VIASA, C.A.*\n`;
            texto += `📋 *Factura Fiscal N°:* ${v.numeroFactura}\n`;
            texto += `👤 *Cliente:* ${v.cliente.nombre} (${v.cliente.rif})\n`;
            texto += `📅 *Fecha:* ${new Date(v.fecha).toLocaleDateString('es-VE')}\n`;
            texto += `----------------------------\n`;
            v.items.forEach(it => {
                texto += `• ${it.cantidad}x ${it.nombre} - $${(it.precioUSD * it.cantidad).toFixed(2)}\n`;
            });
            texto += `----------------------------\n`;
            texto += `💵 *TOTAL USD:* $${v.totalUSD.toFixed(2)}\n`;
            texto += `🇻🇪 *TOTAL BS (BCV):* Bs. ${v.totalBs.toFixed(2)}\n`;
            texto += `🏛️ *Tasa BCV:* Bs. ${v.tasaBCV.toFixed(2)}\n`;
            texto += `¡Muchas gracias por su compra!`;

            const phone = v.cliente.telefono ? v.cliente.telefono.replace(/\D/g, '') : '';
            const url = phone ? `https://wa.me/${phone}?text=${encodeURIComponent(texto)}` : `https://wa.me/?text=${encodeURIComponent(texto)}`;
            window.open(url, '_blank');
        },

        copiarTextoTicket() {
            const v = this.ultimaVenta;
            if (!v) return;

            let texto = `PANADERÍA Y PASTELERÍA NUEVA VIASA, C.A.\nFactura N°: ${v.numeroFactura}\nTotal: $${v.totalUSD.toFixed(2)} / Bs. ${v.totalBs.toFixed(2)}\nTasa BCV: Bs. ${v.tasaBCV.toFixed(2)}`;
            navigator.clipboard.writeText(texto).then(() => {
                alert('📋 Resumen de factura copiado al portapapeles.');
            });
        },

