            csv += `"${calc.id}","${calc.nombreEmpleado}","${calc.cedula}","${calc.cargo}","${calc.frecuencia}",${calc.diasPeriodo},${calc.salarioBaseMensual.toFixed(2)},${calc.salarioBasePeriodo.toFixed(2)},${calc.montoHEDiurna.toFixed(2)},${calc.montoHENocturna.toFixed(2)},${calc.montoDiasFeriados.toFixed(2)},${calc.montoDiasDescanso.toFixed(2)},${calc.bonosEspeciales.toFixed(2)},${calc.bonoCestaticket.toFixed(2)},${calc.totalAsignaciones.toFixed(2)},${calc.ivss.toFixed(2)},${calc.faov.toFixed(2)},${calc.rpe.toFixed(2)},`;
