            csv += `${calc.totalOtrasDeducciones.toFixed(2)},${calc.totalDeducciones.toFixed(2)},${calc.totalNetoUSD.toFixed(2)},${calc.tasaBCV.toFixed(2)},${calc.totalNetoBs.toFixed(2)},"${calc.fechaCalculo}"\n`;

            const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
