        // MODAL DE MOVIMIENTOS BANCARIOS Y CONCILIACIÓN
        // ==============================================================
        abrirModalMovimientoBanco() {
            const modal = document.getElementById('modal-movimiento-banco');
            if (!modal) return;

            document.getElementById('form-movimiento-banco').reset();
            document.getElementById('mov-banco-fecha').value = new Date().toISOString().slice(0, 10);
            document.getElementById('mov-banco-referencia').value = `${Math.floor(100000 + Math.random() * 900000)}`;
            modal.classList.add('active');
        },

        cerrarModalMovimientoBanco() {
            const modal = document.getElementById('modal-movimiento-banco');
            if (modal) modal.classList.remove('active');
        },

        async guardarMovimientoBanco(e) {
            if (e) e.preventDefault();

            const banco = document.getElementById('mov-banco-nombre').value;
            const cuenta = document.getElementById('mov-banco-cuenta').value.trim() || '0102-0192-381920194812';
            const tipo = document.getElementById('mov-banco-tipo').value;
            const fecha = document.getElementById('mov-banco-fecha').value;
            const referencia = document.getElementById('mov-banco-referencia').value.trim();
            const montoUSD = parseFloat(document.getElementById('mov-banco-monto-usd').value) || 0;
            const montoBs = parseFloat(document.getElementById('mov-banco-monto-bs').value) || (montoUSD * this.tasaBCV);
            const concepto = document.getElementById('mov-banco-concepto').value.trim();
            const estado = document.getElementById('mov-banco-estado').value;

            if (montoUSD <= 0) {
                alert('⚠️ Ingrese un monto válido mayor a 0.');
                return;
            }

            const nuevoMov = {
                id: `MOV-BNC-${Date.now().toString().slice(-4)}`,
                banco,
                cuenta,
                tipo,
                montoUSD: parseFloat(montoUSD.toFixed(2)),
                montoBs: parseFloat(montoBs.toFixed(2)),
                fecha,
                referencia,
                concepto,
                estado,
                vinculoOrigen: null
            };

            this.movimientosBanco.unshift(nuevoMov);
            await window.ViasaStorage.guardarColeccion('movimientos_banco', this.movimientosBanco);

            this.cerrarModalMovimientoBanco();
            this.renderContabilidad();

            if (window.ViasaAudio) window.ViasaAudio.playCashChime();
            alert(`🏦 Movimiento bancario registrado exitosamente (${nuevoMov.id}).`);
        },

        async conciliarMovimientoBanco(movId, nuevoEstado) {
            const mov = this.movimientosBanco.find(m => m.id === movId);
            if (!mov) return;

            mov.estado = nuevoEstado || (mov.estado === 'conciliado' ? 'pendiente' : 'conciliado');
            await window.ViasaStorage.guardarColeccion('movimientos_banco', this.movimientosBanco);
            this.renderContabilidad();
            if (window.ViasaAudio) window.ViasaAudio.playClick();
        },

        async autoConciliarMovimientos() {
            let matches = 0;

            // Cruzar movimientos bancarios pendientes con pagos CxP y ventas POS
            for (const mov of this.movimientosBanco) {
                if (mov.estado === 'pendiente') {
                    // Buscar coincidencia en pagos CxP por referencia o monto
                    for (const cxp of this.cuentasPorPagar) {
                        for (const pago of (cxp.pagosRealizados || [])) {
                            if (pago.referencia && mov.referencia && pago.referencia.trim() === mov.referencia.trim()) {
                                mov.estado = 'conciliado';
                                mov.vinculoOrigen = `Pago CxP ${pago.id} (${cxp.proveedorNombre})`;
                                matches++;
                            }
                        }
                    }

                    // Buscar coincidencia en ventas POS con Pago Móvil o POS
                    const ventas = (window.ViasaDatabase && window.ViasaDatabase.ventas ? window.ViasaDatabase.ventas : []);
                    for (const v of ventas) {
                        for (const p of (v.pagos || [])) {
                            if (p.referencia && mov.referencia && p.referencia.trim() === mov.referencia.trim()) {
                                mov.estado = 'conciliado';
                                mov.vinculoOrigen = `Venta POS Fact ${v.numeroFactura}`;
                                matches++;
                            }
                        }
                    }
                }
            }

            await window.ViasaStorage.guardarColeccion('movimientos_banco', this.movimientosBanco);
            this.renderContabilidad();

            if (window.ViasaAudio) window.ViasaAudio.playCashChime();
            alert(`⚡ Auto-Conciliación completada:\n\n- ${matches} movimientos cruzados y conciliados exitosamente.`);
        },

