        exportarReporteExcel(tipoReporte, fInicio, fFin) {
            let csvContent = "\uFEFF"; // UTF-8 BOM
            const fIni = fInicio || '2026-09-01';
            const fFin_ = fFin || '2026-09-30';

            csvContent += `PANADERIA Y PASTELERIA NUEVA VIASA, C.A. - RIF: J-30485920-1\r\n`;
            csvContent += `REPORTE: ${tipoReporte.toUpperCase()} | PERIODO: ${fIni} AL ${fFin_}\r\n`;
            csvContent += `TASA OFICIAL BCV: Bs. ${this.tasaBCV.toFixed(2)}\r\n\r\n`;

            const ventas = (window.ViasaDatabase && window.ViasaDatabase.ventas ? window.ViasaDatabase.ventas : []).concat(this.ultimaVenta ? [this.ultimaVenta] : []);

            if (tipoReporte === 'ventas_cajero') {
                csvContent += `Factura,Fecha,Cajero,Cliente,RIF,Total USD,Total Bs,Forma Pago\r\n`;
                ventas.forEach(v => {
                    csvContent += `"${v.numeroFactura}","${v.fecha.slice(0, 10)}","${v.cajero || 'Cajero'}","${v.cliente?.nombre || 'Consumidor'}","${v.cliente?.rif || 'V-00000000'}",${v.totalUSD.toFixed(2)},${v.totalBs.toFixed(2)},"${(v.pagos || []).map(p => p.metodoId).join(' + ')}"\r\n`;
                });
            } else if (tipoReporte === 'auditoria_mermas') {
                csvContent += `ID Merma,Fecha,Item,Cantidad,Unidad,Motivo,Responsable,Perdida USD,Perdida Bs\r\n`;
                this.mermas.forEach(m => {
                    csvContent += `"${m.id}","${m.fecha.slice(0, 10)}","${m.itemNombre}",${m.cantidad},"${m.unidad}","${m.motivo || m.tipoMerma}","${m.responsable || 'Panadero'}",${m.costoPerdidaUSD.toFixed(2)},${(m.costoPerdidaUSD * this.tasaBCV).toFixed(2)}\r\n`;
                });
            } else if (tipoReporte === 'consolidado_seniat') {
                csvContent += `Reporte Z,Fecha,Ventas Exentas USD,Base Gravada 16% USD,Debito IVA USD,Total USD,Total Bs\r\n`;
                this.cierresCaja.forEach(c => {
                    csvContent += `"${c.reporteZNumero}","${c.fechaCierre.slice(0, 10)}",${(c.totalVentasUSD * 0.6).toFixed(2)},${(c.totalVentasUSD * 0.35).toFixed(2)},${(c.totalVentasUSD * 0.05).toFixed(2)},${c.totalVentasUSD.toFixed(2)},${c.totalVentasBs.toFixed(2)}\r\n`;
                });
            } else if (tipoReporte === 'rentabilidad_recetas') {
                csvContent += `Formula,Categoria,Rendimiento,Costo Unit USD,Precio Venta USD,Margen Ganancia %,Utilidad USD\r\n`;
                this.recetasFormulas.forEach(r => {
                    const cUnit = r.costoUnitarioUSD || 0.5;
                    const pVenta = r.precioSugeridoUSD || (cUnit * 2.2);
                    const util = pVenta - cUnit;
                    const margen = pVenta > 0 ? (util / pVenta) * 100 : 50;
                    csvContent += `"${r.nombre}","${r.categoria}","${r.rendimientoEstimado} piezas",${cUnit.toFixed(2)},${pVenta.toFixed(2)},${margen.toFixed(1)}%,${util.toFixed(2)}\r\n`;
                });
            } else if (tipoReporte === 'estado_cxp') {
                csvContent += `Factura Proveedor,Proveedor,Fecha Emision,Fecha Vencimiento,Total USD,Abonado USD,Saldo Pendiente USD,Estado\r\n`;
                this.cuentasPorPagar.forEach(c => {
                    csvContent += `"${c.numeroFacturaProveedor || c.id}","${c.proveedorNombre}","${c.fechaEmision}","${c.fechaVencimiento}",${c.montoTotalUSD.toFixed(2)},${(c.montoPagadoUSD || 0).toFixed(2)},${c.saldoPendienteUSD.toFixed(2)},"${c.estado}"\r\n`;
                });
            } else {
                csvContent += `Cliente,Documento,Tipo,Compras Totales USD,Puntos Club,Saldo Wallet USD\r\n`;
                this.clientes.forEach(c => {
                    csvContent += `"${c.nombre}","${c.documento}","${c.tipo}",${(c.comprasHistoricasTotalUSD || 0).toFixed(2)},${c.puntosClub || 0},${(c.saldoWalletUSD || 0).toFixed(2)}\r\n`;
                });
            }

            const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
            const link = document.createElement('a');
            const url = URL.createObjectURL(blob);
            link.setAttribute('href', url);
            link.setAttribute('download', `VIASA_Reporte_${tipoReporte}_${fIni}_${fFin_}.csv`);
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);

            if (window.ViasaAudio) window.ViasaAudio.playCashChime();
            alert(`📥 Reporte exportado a Excel/CSV exitosamente.`);
        },

