        descargarSetupBat() {
            const batContent = `@echo off\r\n` +
                `title Instalador VIASA System - Panaderia Nueva Viasa\r\n` +
                `color 0A\r\n` +
                `echo ===================================================================\r\n` +
                `echo   INSTALADOR NATIVO - VIASA SYSTEM (PANADERIA NUEVA VIASA)\r\n` +
                `echo ===================================================================\r\n` +
                `echo.\r\n` +
                `echo [1/3] Configurando entorno local offline-first...\r\n` +
                `set APP_DIR=%~dp0\r\n` +
                `echo Carpeta de aplicacion: %APP_DIR%\r\n` +
                `echo.\r\n` +
                `echo [2/3] Creando acceso directo en el Escritorio...\r\n` +
                `powershell -Command "$WshShell = New-Object -ComObject WScript.Shell; $Shortcut = $WshShell.CreateShortcut([Environment]::GetFolderPath('Desktop') + '\\VIASA System.lnk'); $Shortcut.TargetPath = '%APP_DIR%viasa_app.bat'; $Shortcut.WorkingDirectory = '%APP_DIR%'; $Shortcut.IconLocation = '%APP_DIR%assets\\icons\\viasa_icon.ico'; $Shortcut.Save()"\r\n` +
                `echo.\r\n` +
                `echo [3/3] Instalacion completada con exito!\r\n` +
                `echo.\r\n` +
                `echo Se ha generado el icono 'VIASA System' en su Escritorio.\r\n` +
                `echo Presione cualquier tecla para iniciar VIASA System...\r\n` +
                `pause >nul\r\n` +
                `start "" "%APP_DIR%viasa_app.bat"\r\n`;

            const blob = new Blob([batContent], { type: 'application/bat' });
            const link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            link.download = 'viasa_setup.bat';
            link.click();
        },

        descargarAppBat() {
            const batContent = `@echo off\r\n` +
                `title VIASA System - Panaderia y Pasteleria Nueva Viasa\r\n` +
                `cd /d "%~dp0"\r\n` +
                `echo Iniciando VIASA System en modo Standalone...\r\n` +
                `start msedge --app="%~dp0index.html" || start chrome --app="%~dp0index.html" || start "" "%~dp0index.html"\r\n` +
                `exit\r\n`;

            const blob = new Blob([batContent], { type: 'application/bat' });
            const link = document.createElement('a');
            link.href = URL.createObjectURL(blob);
            link.download = 'viasa_app.bat';
            link.click();
        },

