        guardarYEmitirFiniquitoLOTTT() {
            if (!this.calculoLiquidacionActivo) {
                alert('⚠️ Seleccione un trabajador y calcule la liquidación antes de guardar.');
                return;
            }

            const liq = this.calculoLiquidacionActivo;
            liq.fechaLiquidacion = new Date().toISOString().split('T')[0];
            liq.hashIntegridad = '8f7e2a9b4c1d6e3f5a0b7c8d9e1f2a3b4c5d6e7f8a9b0c1d2e3f4a5b6c7d8e9f';
            liq.archivoLocalPath = `C:\\Users\\Usuario\\VIASA System\\Expedientes_Personal\\LIQ-${liq.id}_${liq.nombreEmpleado.replace(/\s+/g, '_')}.html`;

            this.liquidacionesLOTTT.unshift(liq);
            window.ViasaStorage.guardarColeccion('liquidaciones_lottt', this.liquidacionesLOTTT);

            // Archivar en Banco de Memoria RRHH
            this.bancoMemoriaRRHH.unshift({
                id: `MEM-LIQ-${liq.id}`,
                tipoDocumento: 'liquidacion_lottt',
                titulo: `Finiquito LOTTT - ${liq.nombreEmpleado}`,
                empleadoId: liq.empleadoId,
                nombreEmpleado: liq.nombreEmpleado,
                cedula: liq.cedula,
                cargo: liq.cargo,
                fechaArchivo: new Date().toISOString(),
                fechaLegible: new Date().toLocaleString('es-VE'),
                hashCrypto: liq.hashIntegridad,
                rutaLocal: liq.archivoLocalPath,
                estado: 'inalterable',
                tamanoKB: 32.5
            });
            window.ViasaStorage.guardarColeccion('banco_memoria_rrhh', this.bancoMemoriaRRHH);

            this.cerrarModalCalculadoraLOTTT();
            this.renderRRHH();
            if (window.ViasaAudio) window.ViasaAudio.playCashChime();
            alert(`✅ ¡Finiquito y Liquidación LOTTT (${liq.id}) de ${liq.nombreEmpleado} registrado con éxito y archivado en el Banco de Memoria Digital!`);
        },

