        generarConstanciaTrabajo(empId) {
            const emp = (this.empleados || []).find(e => e.id === empId);
            if (!emp) return;

            this.constanciaTrabajoActiva = emp;
            const modal = document.getElementById('modal-constancia-trabajo-preview');
            const sheet = document.getElementById('constancia-trabajo-print-sheet');

            if (!modal || !sheet) return;

            sheet.innerHTML = this.generarConstanciaTrabajoHTML(emp);
            modal.classList.add('active');
            if (window.ViasaAudio) window.ViasaAudio.playClick();
        },

        cerrarModalConstanciaTrabajo() {
            const modal = document.getElementById('modal-constancia-trabajo-preview');
            if (modal) modal.classList.remove('active');
        },

