                cedula: emp.cedula,
                cargo: emp.cargo,
                fechaArchivo: new Date().toISOString(),
                fechaLegible: new Date().toLocaleString('es-VE'),
                hashCrypto: 'a591a6d40bf420404a011733cfb7b190d62c65bf0bcda32b57b277d9ad9f146e',
                rutaLocal: `C:\\Users\\Usuario\\VIASA System\\Expedientes_Personal\\CONST_${emp.id}_${emp.nombreCompleto.replace(/\s+/g, '_')}.html`,
                estado: 'inalterable',
                tamanoKB: 18.5
