        actualizarVistaPreviaPlanillaEtiquetas() {
            const select = document.getElementById('etq-producto-select');
            const formatoSelect = document.getElementById('etq-formato-select');
            const cantInput = document.getElementById('etq-cantidad-input');
            const chkPrecioDual = document.getElementById('etq-chk-precio-dual');
            const chkFechaLote = document.getElementById('etq-chk-fecha-lote');
            const banner = document.getElementById('etq-info-producto-banner');
            const container = document.getElementById('planilla-etiquetas-render-container');

            if (!select || !container) return;

            const prodId = select.value;
            const prod = (this.productos || []).find(p => p.id === prodId) || (this.productos || [])[0];
            if (!prod) return;

            this.productoEtiquetaActivo = prod;

            // Si el producto no tiene código de barra asignado, asignarle uno oficial EAN-13
            if (!prod.codigoBarras || prod.codigoBarras.length < 8) {
                prod.codigoBarras = window.ViasaCodeEngine.generarEAN13Auto(prod.id.replace(/\D/g, '') || Math.floor(1000 + Math.random() * 8999));
            }

            const eanCompleto = window.ViasaCodeEngine.barcode.formatearEAN13Completo(prod.codigoBarras);
            const formato = formatoSelect ? formatoSelect.value : 'hoja_24';
            const cantidad = cantInput ? (parseInt(cantInput.value, 10) || 24) : 24;
            const mostrarDual = chkPrecioDual ? chkPrecioDual.checked : true;
            const mostrarLote = chkFechaLote ? chkFechaLote.checked : true;

            const precioBs = (prod.precioUSD || 0) * this.tasaBCV;
            const hoyStr = new Date().toLocaleDateString('es-VE');
            const loteStr = `L-${new Date().toISOString().slice(2, 10).replace(/-/g, '')}`;

            // Banner superior de metadatos
            if (banner) {
                banner.innerHTML = `
                    <div style="display: flex; align-items: center; gap: 10px;">
                        <span style="font-weight: 900; font-size: 0.92rem; color: #ffffff;">${prod.nombre}</span>
                        <span class="badge blue">${prod.categoria ? prod.categoria.replace('cat_', '').toUpperCase() : 'GENERAL'}</span>
                        ${prod.produccionPropia ? '<span class="badge gold">🥖 Producción Propia VIASA</span>' : ''}
                    </div>
                    <div style="display: flex; gap: 12px; align-items: center;">
                        <span>EAN-13: <strong style="color: #fbbf24; font-family: monospace; font-size: 0.88rem;">${eanCompleto}</strong></span>
                        <span>Precio: <strong style="color: #4ade80;">$${(prod.precioUSD || 0).toFixed(2)}</strong> (Bs. ${precioBs.toLocaleString('es-VE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })})</span>
                    </div>
                `;
            }

            // Configurar clase de cuadrícula
            container.className = `planilla-etiquetas-grid ${formato.replace('_', '-')}`;
            container.innerHTML = '';

            // Generar N tarjetas de etiquetas
            for (let i = 0; i < cantidad; i++) {
                const card = document.createElement('div');
                card.className = 'etiqueta-anaquel-card';
                card.innerHTML = `
                    <div class="etq-brand">
                        <span class="etq-brand-name">PANADERÍA NUEVA VIASA</span>
                        <span class="etq-brand-rif">RIF: J-31163165-8</span>
                    </div>

                    <div class="etq-prod-title">${prod.nombre}</div>

                    ${mostrarDual ? `
                        <div class="etq-prices-row">
                            <span class="etq-price-usd">$ ${(prod.precioUSD || 0).toFixed(2)}</span>
                            <span class="etq-price-bs">Bs. ${precioBs.toLocaleString('es-VE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
                        </div>
                    ` : ''}

                    <div class="etq-barcode-wrapper">
                        <canvas class="etq-canvas-barcode-item" id="barcode-canvas-item-${i}"></canvas>
                    </div>

                    ${mostrarLote ? `
                        <div class="etq-meta-foot">
                            <span>Lote: <b>${loteStr}</b></span>
                            <span>Env: <b>${hoyStr}</b></span>
                            <span>Tasa BCV: <b>${this.tasaBCV.toFixed(2)}</b></span>
                        </div>
                    ` : ''}
                `;
                container.appendChild(card);

                // Renderizar el código de barra en el canvas de esta etiqueta
                const canvasEl = card.querySelector(`#barcode-canvas-item-${i}`);
                if (canvasEl && window.ViasaCodeEngine) {
                    window.ViasaCodeEngine.barcode.renderBarcodeCanvas(canvasEl, eanCompleto, {
                        formato: 'EAN13',
                        anchoBarra: 1.8,
                        alto: 40,
                        fontSize: 11,
                        margen: 4
                    });
                }
            }
        },

