        async exportarDocumentoPDF(docId = null) {
            const doc = (this.documentosMercantiles || []).find(d => d.id === docId || d.ncu === docId) || 
                        (this.bancoMemoriaDocumental || []).find(m => m.id === docId || m.documentoId === docId)?.documentoCompleto || 
                        this.ultimoDocumentoExpedido;
            if (!doc) {
                alert('⚠️ No se encontró el documento para exportar a PDF.');
                return;
            }

            await this.ejecutarImpresionAislada(doc, true);
        },

        async ejecutarImpresionAislada(doc, isPDF = false) {
            const htmlContent = await this.generarHTMLDocumentoAutocontenido(doc);
            const docTitle = `VIASA_${doc.tipo.toUpperCase()}_NCU_${doc.ncu}`;
            
            let iframe = document.getElementById('viasa-print-isolated-frame');
            if (!iframe) {
                iframe = document.createElement('iframe');
                iframe.id = 'viasa-print-isolated-frame';
                iframe.style.position = 'fixed';
                iframe.style.right = '0';
                iframe.style.bottom = '0';
                iframe.style.width = '0';
                iframe.style.height = '0';
                iframe.style.border = 'none';
                iframe.style.opacity = '0';
                iframe.style.pointerEvents = 'none';
                iframe.style.zIndex = '-9999';
                document.body.appendChild(iframe);
            }

            const prevTitle = document.title;
            document.title = docTitle;

            const docFrame = iframe.contentWindow.document;
            docFrame.open();
            docFrame.write(htmlContent);
            docFrame.close();

            setTimeout(() => {
                try {
                    iframe.contentWindow.focus();
                    iframe.contentWindow.print();
                } catch (e) {
                    window.print();
                }
                setTimeout(() => {
                    document.title = prevTitle;
                }, 1500);
            }, 350);
        },

