        async crearOrdenProduccionDesdeProyeccion() {
            if (!this.proyeccionProduccionMadrugada) return;

            const nuevaOrden = {
                id: `ORD-MAD-${Date.now().toString().slice(-4)}`,
                fecha: this.proyeccionProduccionMadrugada.fecha,
                turno: 'Madrugada (03:00 AM)',
                totalSacos: this.proyeccionProduccionMadrugada.totalSacos,
                unidadesEsperadas: this.proyeccionProduccionMadrugada.totalSalados + this.proyeccionProduccionMadrugada.totalDulces,
                estado: 'En Proceso',
                responsable: 'Maestro Panadero de Guardia'
            };

            this.ordenesProduccion.push(nuevaOrden);
            await window.ViasaStorage.guardarRegistro('ordenes_produccion', nuevaOrden);

            this.cerrarModalProyeccionProduccionMadrugada();
            if (window.ViasaAudio) window.ViasaAudio.playSuccess();
            alert(`🔥 ¡Orden de Producción de Madrugada creada y transmitida a KDS Panadería!\n\nMeta: ${nuevaOrden.unidadesEsperadas} unidades panaderas.\nAmasado programado a las 03:00 AM.`);
        },

        // ----------------------------------------------------------------------
        // MÓDULO 5: PANEL DE ESTADÍSTICAS Y GRÁFICAS FINANCIERAS (BI)
        // ----------------------------------------------------------------------
        renderGraficosFinancierosBI() {
            const container = document.getElementById('reportes-bi-dashboard-container');
            if (!container) return;

            const ventasDual = {
                usd: 4850.00,
                bs: (4850.00 * this.tasaBCV).toFixed(2),
                margenBrutoPct: 58.4,
                costoNominaUSD: 1450.00,
                utilidadNetaUSD: 1380.00
            };

            return ventasDual;
        }
